const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程 2x + 3 = 5x + 7' },
      { kind: 'text', payload: '① 移项' },
      { kind: 'text', payload: '2x - 5x = 7 - 3' },
      { kind: 'text', payload: '② 合并同类项' },
      { kind: 'text', payload: '-3x = 4' },
      { kind: 'text', payload: '③ 系数化为 1' },
      { kind: 'text', payload: 'x = -4/3' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var paths = [];
    var children = [];

    function rr(x, y, w, h, r) {
      return [['M', x + r, y], ['L', x + w - r, y], ['Q', x + w, y, x + w, y + r],
              ['L', x + w, y + h - r], ['Q', x + w, y + h, x + w - r, y + h],
              ['L', x + r, y + h], ['Q', x, y + h, x, y + h - r],
              ['L', x, y + r], ['Q', x, y, x + r, y], ['Z']];
    }
    function addFill(id, cmds, fill) {
      paths.push({ id: id, commands: cmds });
      children.push({ type: 'path', pathId: id, fill: fill });
    }
    function addLine(id, cmds, fill, w) {
      paths.push({ id: id, commands: cmds });
      children.push({ type: 'path', pathId: id, fill: fill,
                      stroke: { width: w, cap: 'round', join: 'round' } });
    }
    function addLabel(idx, x, y, hAlign, vAlign, color) {
      children.push({ type: 'label', contentId: metrics[idx].contentId,
                      anchor: { x: x, y: y }, hAlign: hAlign, vAlign: vAlign,
                      color: color });
    }

    addFill('bg', [['M', 0, 0], ['L', W, 0], ['L', W, H], ['L', 0, H], ['Z']], '#FFFFFF');

    addLabel(0, W / 2, 0.075 * H, 'center', 'middle', '#12304D');

    var uh = Math.max(2, 0.008 * H);
    var uy = 0.112 * H;
    addFill('titleRule', rr(W / 2 - 0.09 * W, uy, 0.18 * W, uh, uh / 2), '#2F6FEB');

    var left = 0.06 * W;
    var cardW = 0.88 * W;
    var cardH = 0.215 * H;
    var gap = 0.04 * H;
    var top0 = 0.16 * H;
    var aw = Math.min(10, cardW * 0.03);
    var titles = [1, 3, 5];
    var exprs = [2, 4, 6];
    var i, top, cr;

    for (i = 0; i < 3; i++) {
      top = top0 + i * (cardH + gap);
      cr = Math.min(16, cardH * 0.18);
      addFill('card' + i, rr(left, top, cardW, cardH, cr), '#F2F7FC');
      addFill('acc' + i, rr(left, top, aw, cardH, aw / 2), '#2F6FEB');
      addLabel(titles[i], left + aw + 0.055 * W, top + 0.3 * cardH, 'left', 'middle', '#1F3A5F');
      addLabel(exprs[i], W / 2, top + 0.72 * cardH, 'center', 'middle', '#0E2A45');
    }

    var j, y1, y2, hs, hw, sw;
    sw = Math.max(1, Math.min(3, H * 0.005));
    for (j = 0; j < 2; j++) {
      y1 = top0 + j * (cardH + gap) + cardH + gap * 0.15;
      y2 = top0 + (j + 1) * (cardH + gap) - gap * 0.15;
      hs = Math.min(10, (y2 - y1) * 0.5);
      hw = hs * 0.85;
      addLine('ar' + j, [['M', W / 2, y1], ['L', W / 2, y2 - hs]], '#5C7FA8', sw);
      addFill('ah' + j, [['M', W / 2 - hw, y2 - hs], ['L', W / 2 + hw, y2 - hs],
                         ['L', W / 2, y2], ['Z']], '#5C7FA8');
    }

    return {
      schemaVersion: 1,
      sceneId: 'linear-equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
